use vstd::prelude::*;

verus! {
    fn has_only_one_distinct_element(a: &Vec<i32>) -> (result: bool)
        ensures
            result == true ==> (a.len() == 0 || forall |i: nat, j: nat| (i < a.len() && j < a.len() ==> a[i] == a[j])),
            result == false ==> exists |i: nat, j: nat| (i < a.len() && j < a.len() && a[i] != a[j]),
    {
        if a.len() == 0 {
            return true; // An empty array has only one distinct value (none).
        }

        let first_value = a[0];
        let mut i: usize = 1;

        while i < a.len()
            invariant
                1 <= i <= a.len(),
                forall |j: nat| (j < i ==> a[j] == first_value),
            decreases a.len() - i,
        {
            if a[i] != first_value {
                return false; // Found a different value, return false.
            }
            i = i + 1;
        }

        true // All elements are equal to the first element.
    }
}
